[McpServerToolType]
public sealed class SavedFinalizationTools(BridgeSession session)
{
    [McpServerTool(Name="execute_owned_saved_finalization",ReadOnly=false,Destructive=true,Idempotent=false,OpenWorld=false),Description("Close once an explicitly disposable owned saved Result in its original named active-last single-view window, after fresh saved-result restoration and file/provenance/context guards. Requires an independently prepared immutable seed/checkpoint; preserves their bytes and all other files/windows while recording possible serialization changes of the owned writer. The writer original SaveAs hash is historical after finalization. Consumes CAD leases before IPC; requires separate close verification. No Save, geometry, activation, close-all or retry. Full only; cannot close arbitrary/unsaved documents.")]
    public Task<CallToolResult> Execute([Description("Current observed saved-result handle from restore_owned_saved_result in this connection.")]string savedResultHandle,[Description("Fresh candidate of the disposable current saved Result.")]string candidateDocumentHandle,[Description("Fresh one-use active window choice.")]string activeDocumentHandle,[Description("Explicit decision finalize_owned_saved_result_with_sealed_bytes for this owned saved window only.")]string disposition,[Description("Original successful existing saved-reopen seed preparation request ID.")]string seedPreparationRequestId,[Description("SHA256 of its raw Native preparation receipt.")]string seedPreparationReceiptSha256,CancellationToken cancellationToken)=>Run(false,savedResultHandle,null,null,candidateDocumentHandle,activeDocumentHandle,disposition,seedPreparationRequestId,seedPreparationReceiptSha256,cancellationToken);
    [McpServerTool(Name="verify_owned_saved_finalization",ReadOnly=false,Destructive=false,Idempotent=false,OpenWorld=false),Description("Independently verify one original returned owned saved Result close using fresh remaining-context observations, immutable original plan/claim/receipt, sealed files, actual finalized writer fingerprint and journal. May append terminal success and release only its matching result-close fence. No close, save, activation, geometry, replay or new edit binding. Missing authoritative command return cannot be inferred. Full only.")]
    public Task<CallToolResult> Verify([Description("Original Native saved-result close request ID.")]string closeRequestId,[Description("Exact SHA256 of its immutable raw receipt.")]string closeReceiptSha256,[Description("Fresh candidate of the remaining active document after close.")]string candidateDocumentHandle,[Description("Fresh one-use choice of that remaining active window.")]string activeDocumentHandle,CancellationToken cancellationToken)=>Run(true,null,closeRequestId,closeReceiptSha256,candidateDocumentHandle,activeDocumentHandle,null,null,null,cancellationToken);
    async Task<CallToolResult> Run(bool verify,string? handle,string? id,string? sha,string candidate,string active,string? disposition,string? seedId,string? seedSha,CancellationToken ct)
    {
        string name=verify?"verify_owned_saved_finalization":"execute_owned_saved_finalization";session.AssertToolAllowed(name);bool gate=false,submitted=false;string? request=null;var timer=Stopwatch.StartNew();
        CallToolResult Fail(string state){var value=new JsonObject{["state"]=state,["retryAllowed"]=false,["contextChangeMayHaveOccurred"]=submitted&&!verify,["verificationMayBePartial"]=submitted&&verify,["cadSaveAttempted"]=false,["geometryMutationAttempted"]=false};if(request is not null)value["bridgeRequestId"]=request;return DiagnosticTools.Result(value,true);}
        try{gate=await session.ReferenceGate.WaitAsync(session.Options.Timeout,ct);if(!gate)return Fail("queue_timeout_before_submission");ct.ThrowIfCancellationRequested();if(File.Exists(FileArtifacts.FixedPath(session.Options.BridgeRoot,"maintenance.json")))return Fail("maintenance_before_submission");var args=verify?SavedFinalizationProof.VerifyParameters(session,id!,sha!,candidate,active):SavedFinalizationProof.Parameters(session,handle!,candidate,active,disposition!,seedId!,seedSha!);var remaining=session.Options.Timeout-timer.Elapsed;if(remaining<=TimeSpan.Zero)return Fail("queue_timeout_before_submission");ct.ThrowIfCancellationRequested();if(!verify)session.RevokeCadLeases(true);submitted=true;
            var result=await session.Ipc.SubmitAsync("recipe.prepare",new(){["recipeId"]=name,["parameters"]=args},ct,remaining);request=result["bridgeRequestId"]?.GetValue<string>();if(ct.IsCancellationRequested||timer.Elapsed>=session.Options.Timeout)return Fail("owned_saved_finalization_outcome_unknown");
            if(result["state"]?.GetValue<string>()==(verify?"owned_saved_finalization_verified":"owned_saved_finalization_executed_unverified")){if(verify)SavedFinalizationProof.Verification(session,result,args);else SavedFinalizationProof.Execution(session,result,args);if(ct.IsCancellationRequested||timer.Elapsed>=session.Options.Timeout)return Fail("owned_saved_finalization_outcome_unknown");return DiagnosticTools.Result(result);}result["retryAllowed"]=false;return DiagnosticTools.Result(result,true);
        }catch(OperationCanceledException)when(ct.IsCancellationRequested){return Fail(submitted?"owned_saved_finalization_outcome_unknown":"cancelled_before_submission");}
        catch(Exception e)when(e is ReferenceRejected or InvalidDataException or IOException or UnauthorizedAccessException or System.Text.Json.JsonException or InvalidOperationException or KeyNotFoundException or FormatException or NullReferenceException){return Fail(submitted?"owned_saved_finalization_outcome_unknown":"owned_saved_finalization_rejected");}
