    }
    internal static JsonObject Schema(bool verify){var fields=verify?new[]{"closeRequestId","closeReceiptSha256","candidateDocumentHandle","activeDocumentHandle"}:new[]{"savedResultHandle","candidateDocumentHandle","activeDocumentHandle","disposition","seedPreparationRequestId","seedPreparationReceiptSha256"};var p=new JsonObject();var r=new JsonArray();foreach(var field in fields){p[field]=field=="disposition"?new JsonObject{["type"]="string",["enum"]=new JsonArray("finalize_owned_saved_result_with_sealed_bytes")}:new JsonObject{["type"]="string",["pattern"]=field.EndsWith("Sha256",StringComparison.Ordinal)?"^[0-9a-f]{64}$":"^[0-9a-f]{32}$"};r.Add(field);}return new(){["type"]="object",["properties"]=p,["required"]=r,["additionalProperties"]=false};}
    public static McpServerTool[] Create(BridgeSession s)=>!s.ExecutionEnabled("execute_owned_saved_finalization")?[]:[new StrictTool(McpServerTool.Create(new SavedFinalizationTools(s).Execute),s,Schema(false)),new StrictTool(McpServerTool.Create(new SavedFinalizationTools(s).Verify),s,Schema(true))];
